const locale = document.documentElement.lang || "en"
const formats = {
  time: new Intl.DateTimeFormat(locale, { hour: "numeric", minute: "2-digit" }),
  date: new Intl.DateTimeFormat(locale, { month: "short", day: "numeric" }),
  date_with_year: new Intl.DateTimeFormat(locale, { month: "short", day: "numeric", year: "numeric" }),
  weekday: new Intl.DateTimeFormat(locale, { weekday: "long", month: "long", day: "numeric" }),
  datetime: new Intl.DateTimeFormat(locale, { dateStyle: "short", timeStyle: "short" })
}
const relativeDays = new Intl.RelativeTimeFormat(locale, { numeric: "auto" })

export function formatLocalTime(date, format, now = new Date()) {
  if (format === "relative" || format === "due") {
    const days = signedDifferenceInDays(now, date)

    if (format === "due") return relativeDays.format(Math.max(0, days), "day")
    if (days === 0) return formats.time.format(date)
    if (Math.abs(days) < 7) return relativeDays.format(days, "day")

    format = date.getFullYear() === now.getFullYear() ? "date" : "date_with_year"
  }

  return formats[format].format(date)
}

export function signedDifferenceInDays(fromDate, toDate) {
  return (calendarDay(toDate) - calendarDay(fromDate)) / 86_400_000
}

// Compare local calendar dates, not elapsed time: a day spanning a DST change
// can be 23 or 25 hours long.
function calendarDay(date) {
